from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
l=Lesson('Écoulement auriculaire')
l.add('L’otorrhée est un écoulement provenant du conduit auditif externe. Les {distinctions utiles} séparent sécrétion inflammatoire, pus, sang et liquide clair. L’aspect seul ne suffit pas à déterminer son origine.',paras('Le liquide peut provenir de la peau du conduit ou de l’oreille moyenne à travers une perforation ou un aérateur transtympanique. Un écoulement sanguin est une otorragie ; il peut accompagner une infection, un traumatisme ou une lésion du conduit.', 'Un écoulement clair ne signifie pas automatiquement fuite de liquide cérébrospinal. Le contexte traumatique, opératoire et neurologique est déterminant ; une fuite suspectée exige un bilan spécialisé.', 'Le cérumen normal n’est pas une otorrhée infectieuse. Il faut identifier une vraie sécrétion et examiner l’oreille plutôt que traiter sa couleur.'),(1,4,5,6))
l.add('Otites externes et otites moyennes perforées font partie des causes importantes en pratique. Les {contextes de survenue} orientent davantage qu’un rang unique. Une cause rare mais grave doit être recherchée sans attendre.',paras('Baignade, humidité, grattage et manipulation favorisent une inflammation du conduit. Une infection respiratoire récente et une otalgie précédant l’écoulement orientent vers l’oreille moyenne.', 'L’enfant peut avoir introduit un objet sans le dire. Chez une personne diabétique ou immunodéprimée, une douleur persistante disproportionnée impose de rechercher une infection invasive.', 'L’ordre des dix diagnostics est pédagogique et ne constitue pas un classement chiffré de prévalence suisse. Il rassemble causes courantes, persistantes, traumatiques et urgences.'),(1,2,3,9,11))
anatomie=l.subwindow('anatomie','Conduit, tympan et oreille moyenne',paras('Le conduit auditif externe est tapissé de peau et se termine sur le tympan. Le cérumen et la migration épithéliale contribuent à sa protection ; humidité et microtraumatismes peuvent perturber cette barrière.', 'Le tympan sépare le conduit de la caisse de l’oreille moyenne. Une perforation ou un drain crée une communication : le pus provenant de l’oreille moyenne peut devenir visible à l’extérieur.', 'La mastoïde communique avec l’oreille moyenne. Une infection compliquée peut s’étendre aux structures voisines ; un cholestéatome accumule de la kératine et peut éroder l’os.', 'Une obstruction du conduit ou une atteinte tympano-ossiculaire peut causer une surdité de transmission. Une atteinte cochléaire ou neurologique doit être évoquée devant une surdité de perception ou des signes vestibulaires.'),(3,4,5))
l.add('La {localisation anatomique} explique la plupart des présentations. Une sécrétion du conduit et une sécrétion traversant le tympan peuvent se ressembler. L’intégrité tympanique conditionne aussi la sécurité des traitements locaux.',paras(anatomie)+paras('Une dermatite peut suinter sans infection bactérienne initiale. Une prolifération fongique ou une allergie aux produits instillés peut entretenir les symptômes malgré des antibiotiques.', 'La douleur au tragus soutient une origine externe, mais ne remplace pas l’examen du tympan. L’absence de douleur importante n’exclut pas une maladie chronique destructrice.'),(1,3,4,7,12))
l.add('Les {signes d’alarme} précèdent le choix des gouttes. Une urgence neurologique, traumatique ou infectieuse nécessite une filière hospitalière. Une pile bouton doit être retirée immédiatement.',table(['Priorité','🚩 Présentation','Décision'],[['E1 — Atteinte générale ou intracrânienne.','Altération de conscience, syndrome méningé, sepsis ou déficit neurologique.','Appel 144 selon gravité ; prise en charge hospitalière immédiate.'],['E2 — Traumatisme.','Écoulement clair ou sanglant après traumatisme crânien, paralysie faciale, surdité ou vertige.','Bilan traumatique urgent ; pas d’instrumentation profonde ni d’irrigation.'],['E3 — Infection invasive.','Douleur profonde nocturne ou disproportionnée, diabète, immunodépression, granulations ou nerf crânien atteint.','Suspecter otite externe nécrosante ; avis ORL urgent.'],['E4 — Mastoïdite ou extension.','Tuméfaction rétroauriculaire douloureuse, pavillon décollé, fièvre ou extension aux tissus voisins.','Évaluation hospitalière urgente.'],['E5 — Corps étranger dangereux.','Pile bouton connue ou suspectée.','Retrait immédiat par équipe équipée ; ne pas irriguer.'],['Bilan rapide.','Otorrhée persistante, masse, saignement récidivant ou baisse auditive progressive.','Rechercher cholestéatome ou tumeur ; ne pas multiplier les traitements empiriques.']]),(2,3,4,5,7,8,9,10,11,12,16,17))
l.add('L’entretien précise début, récidives et symptômes associés. Les {questions ciblées} recherchent terrain à risque, chirurgie et exposition locale. Un traitement déjà essayé doit être identifié par son nom exact.',table(['Question','Ce qu’elle apporte'],[['Début aigu, récidivant ou écoulement continu ?','Distinguer épisode récent et maladie chronique.'],['Douleur avant ou après le début de l’écoulement ?','Une otalgie diminuant lors de la perforation oriente vers une otite moyenne.'],['Prurit, baisse auditive, vertige, acouphènes, fièvre ?','Préciser atteinte cutanée, auditive, vestibulaire ou complication.'],['Baignade, coton-tige, objet, gifle, plongée ou choc crânien ?','Rechercher porte d’entrée et traumatisme.'],['Tympan perforé, drains ou opération antérieure ?','Adapter examen et traitement local.'],['Diabète, immunodépression, radiothérapie ?','Identifier risque de complication.'],['Gouttes, appareil auditif, bouchons, produits cosmétiques ?','Rechercher irritation ou allergie de contact.'],['Chez l’enfant, objet accessible ou pile manquante ?','Ne pas manquer un corps étranger dangereux.']]),(2,3,5,6,7,9,12))
l.add('L’examen associe état général, pavillon, région mastoïdienne et otoscopie prudente. Les {constats décisifs} localisent la lésion et recherchent une complication. Un tympan non visible ne doit pas être considéré intact.',paras('Noter douleur au tragus ou à la mobilisation du pavillon, œdème, rougeur, débris, corps étranger, granulation ou lésion focale. Examiner l’autre oreille et rechercher une asymétrie faciale ou un déficit neurologique.', 'Visualiser si possible le tympan après nettoyage adapté par une personne formée. Décrire perforation, drain, bombement, poche de rétraction et débris kératiniques ; une aspiration sous contrôle peut être nécessaire.', 'Apprécier l’audition, puis compléter selon besoin par tests au diapason et audiométrie. Une baisse auditive soudaine ou un vertige marqué justifie une évaluation urgente.', 'Ne pas procéder à un lavage à l’aveugle. Éviter l’irrigation si perforation possible, antécédent chirurgical à risque, pile bouton ou matière pouvant gonfler.'),(3,4,5,6,7,9))
l.add('Le {tableau comparatif} rapproche chaque profil d’une décision. Les diagnostics peuvent coexister, par exemple perforation et infection externe. Les signes de gravité priment toujours sur l’ordre de présentation.',comparison(),(1,2,3,4,5,6,7,9,11,12))
l.add('Le diagnostic repose sur la localisation clinique et l’otoscopie. Les {critères d’orientation} évitent d’étiqueter toute otorrhée comme une otite externe. Une récidive ou un échec nécessite de réexaminer la cause.',paras('Conduit inflammatoire et douleur au tragus orientent vers une otite externe. Pus traversant une perforation après otalgie aiguë oriente vers une otite moyenne perforée.', 'Une perforation ancienne avec écoulement récidivant suggère une otite chronique. Kératine, poche de rétraction ou polype imposent de rechercher un cholestéatome ; un simple traitement de l’écoulement ne suffit pas.', 'Prurit et débris fongiques suggèrent une otomycose, tandis que desquamation et exposition répétée orientent vers une dermatite. Aucun de ces signes ne dispense d’exclure une complication selon le terrain.', 'Un écoulement clair persistant, surtout après chirurgie ou traumatisme, demande confirmation spécialisée de son origine. Ne pas conclure à une fuite ou l’exclure sur sa seule apparence.'),(1,2,3,4,5,7,12))
l.add('Les examens complémentaires répondent à une question précise. Le {bilan dirigé} dépend de la gravité et de la persistance. Une imagerie n’est pas systématique dans une otite externe simple.',table(['Situation','Bilan utile'],[['Otite externe simple.','Examen clinique ; prélèvement si nécessaire selon traitement choisi, échec, récidive ou terrain.'],['Tympan non visualisé ou écoulement persistant.','Otomicroscopie et nettoyage adapté ; culture si infection persistante ou atypique.'],['Hypoacousie ou maladie chronique.','Audiométrie et bilan ORL ; imagerie selon suspicion de cholestéatome ou complication.'],['Otite nécrosante suspectée.','Bilan biologique, microbiologique et imagerie spécialisée, souvent scanner et/ou IRM.'],['Traumatisme crânien ou fuite suspectée.','Imagerie de traumatisme et des rochers selon situation ; analyse spécialisée du liquide.'],['Lésion focale persistante, polype ou saignement.','Avis ORL ; prélèvement histologique si indiqué pour exclure une tumeur.']]),(3,4,5,7,11,12,13))
l.add('L’{algorithme pratique} commence par la gravité et l’état du tympan. Il mène ensuite au traitement de la cause. La réévaluation fait partie de la décision initiale.',steps('Rechercher traumatisme majeur, signes neurologiques, infection invasive, mastoïdite et pile bouton ; orienter en urgence si présents.', 'Examiner conduit et tympan sans geste dangereux ; demander un examen spécialisé si la visibilité ou le contexte ne permet pas une décision sûre.', 'Distinguer atteinte externe, moyenne, traumatique, corps étranger et fuite suspectée ; tenir compte des drains et de la chirurgie.', 'Choisir le traitement compatible avec la cause, la formulation et le tympan ; traiter la douleur et expliquer les soins.', 'Pour une otite externe traitée, réévaluer si absence d’amélioration en 48 à 72 heures, plus tôt si aggravation. Rechercher erreur de diagnostic, obstacle, mauvaise pénétration, allergie, mycose ou complication.', 'Devant une otorrhée chronique ou récidivante, organiser bilan ORL et auditif et rechercher un cholestéatome.'),(2,3,4,5,7,9,11))
l.add('La prise en charge dépend de la cause et de la préparation exacte. Les {principes thérapeutiques suisses} associent antalgie, soins adaptés et suivi. Une recommandation portant sur une molécule ne rend pas toutes ses formulations interchangeables.',paras('Une otite externe bactérienne non compliquée relève généralement d’un traitement local et du maintien d’un conduit accessible. Une extension, un terrain à risque ou une suspicion d’otite nécrosante peut nécessiter antibiothérapie systémique et prise en charge spécialisée.', 'En Suisse, Ciproxin HC associe ciprofloxacine et hydrocortisone et est contre-indiqué si une perforation tympanique est connue ou supposée. Panotile est également contre-indiqué en cas de perforation ; sa néomycine expose à une ototoxicité. Ces préparations ne doivent pas être choisies à l’aveugle pour une oreille qui coule.', 'Ciloxan possède une information professionnelle suisse ophtalmique. Son utilisation dans l’oreille constitue un usage hors information professionnelle ; une posologie oculaire ne doit pas être transposée. En cas de tympan ouvert, le choix d’une préparation non ototoxique et de son schéma doit être validé avec l’ORL et le pharmacien.', 'L’otite moyenne aiguë perforée peut tirer davantage bénéfice d’une antibiothérapie que certaines formes non perforées ; évaluer âge, gravité et suivi selon les recommandations suisses. Les gouttes destinées à une otite externe ne remplacent pas cette décision.', 'Un cholestéatome nécessite un traitement de la maladie, généralement chirurgical. Une mycose, une dermatite, un corps étranger ou une fuite de liquide cérébrospinal ne se résume pas à une prescription antibiotique.'),(2,4,7,8,13,14,15))
l.add('Les {mesures de prévention} réduisent humidité et traumatismes. Les consignes doivent être adaptées aux perforations et aux dispositifs auditifs. Une nouvelle douleur ou un écoulement persistant justifie un contrôle.',paras('Éviter cotons-tiges, grattage et introduction d’objets. Pendant un épisode ou en cas de tympan ouvert, protéger l’oreille de l’eau selon les conseils du professionnel ; ne pas introduire de produit domestique.', 'Nettoyer et entretenir appareils auditifs et embouts selon leurs instructions, puis rechercher une irritation ou une allergie si les symptômes récidivent. Adapter les protections auditives sans traumatiser le conduit.', 'Conserver piles bouton hors d’accès des enfants. Expliquer les modalités des gouttes prescrites et les signes imposant une consultation immédiate ; ne pas réutiliser automatiquement un ancien flacon.'),(3,7,9,10,12,13))
l.add('Otorrhée et otite externe ne sont pas synonymes. Le tympan doit être évalué avant de choisir des gouttes. Douleur disproportionnée, déficit neurologique, traumatisme et pile bouton changent l’urgence. Toute persistance impose de réexaminer la cause.',refs=(1,4,5,7,9,11,13,15))
l.quiz([('Une otorrhée prouve-t-elle une otite externe ?','Non : elle peut provenir de l’oreille moyenne, d’un traumatisme ou d’une autre cause.'),('Un tympan masqué par du pus peut-il être considéré intact ?','Non : il faut adapter l’examen et le traitement à cette incertitude.'),('Quelle douleur oriente vers le conduit externe ?','Une douleur au tragus ou à la mobilisation du pavillon, associée à une inflammation du conduit.'),('Le soulagement d’une otalgie lors d’un écoulement est-il toujours rassurant ?','Non : il peut traduire une perforation d’otite moyenne.'),('Une otorrhée chronique peu douloureuse exclut-elle un cholestéatome ?','Non : la chronicité et l’examen du tympan sont essentiels.'),('Une pile bouton peut-elle attendre un rendez-vous ordinaire ?','Non : son retrait est une urgence immédiate.'),('Peut-on irriguer une oreille contenant une pile ?','Non : l’irrigation est contre-indiquée.'),('Que rechercher devant une douleur nocturne disproportionnée chez un diabétique ?','Une otite externe nécrosante, qui nécessite une évaluation urgente.'),('Une tuméfaction rétroauriculaire avec pavillon décollé évoque-t-elle une simple dermatite ?','Non : rechercher notamment une mastoïdite.'),('Un liquide clair après choc crânien peut-il être banalisé ?','Non : une fuite de liquide cérébrospinal et des lésions associées doivent être recherchées.'),('Ciproxin HC convient-il à toute otorrhée parce qu’il contient de la ciprofloxacine ?','Non : l’AIPS contre-indique cette préparation si perforation connue ou supposée.'),('La dose oculaire de Ciloxan fournit-elle une dose auriculaire autorisée ?','Non : l’information suisse est ophtalmique ; l’usage auriculaire est hors information professionnelle.'),('Quand réexaminer une otite externe qui ne s’améliore pas sous traitement ?','En 48 à 72 heures, ou immédiatement si aggravation ou signe d’alarme.'),('Faut-il multiplier les antibiotiques devant un prurit persistant ?','Non : rechercher mycose, dermatite, allergie, obstacle ou autre diagnostic.')],(1,2,3,4,5,7,9,10,11,13,14,15))
l.write()
